import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import API from '../services/api';

function Devices() {

    const [devices, setDevices] = useState([]);
    const [loading, setLoading] = useState(true);

    // Add device form
    const [showAddForm, setShowAddForm] = useState(false);
    const [newName, setNewName] = useState('');
    const [newLimit, setNewLimit] = useState(1000);
    const [newAutoOff, setNewAutoOff] = useState('');

    // Newly created device, shown once in a "copy this into your sensor" panel
    const [justCreated, setJustCreated] = useState(null);

    // Inline edit state: deviceId -> { name, powerLimit, autoOffMinutes }
    const [editing, setEditing] = useState(null);
    const [editValues, setEditValues] = useState({});

    const [revealedKeys, setRevealedKeys] = useState({});
    const [busyId, setBusyId] = useState(null);

    const apiBase = process.env.REACT_APP_API_URL || 'http://localhost:5000';

    const fetchDevices = async () => {
        try {
            const res = await API.get('/device');
            setDevices(res.data);
        } catch (error) {
            console.log(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchDevices();
    }, []);

    const handleAddDevice = async () => {
        if (!newName.trim()) {
            alert('Please enter a device name');
            return;
        }
        try {
            const res = await API.post('/device', {
                name: newName.trim(),
                powerLimit: Number(newLimit) || 1000,
                autoOffMinutes: newAutoOff ? Number(newAutoOff) : null
            });
            setDevices([res.data, ...devices]);
            setJustCreated(res.data);
            setNewName('');
            setNewLimit(1000);
            setNewAutoOff('');
            setShowAddForm(false);
        } catch (error) {
            alert(error.response?.data?.message || 'Could not add device');
        }
    };

    const startEdit = (device) => {
        setEditing(device._id);
        setEditValues({
            name: device.name,
            powerLimit: device.powerLimit,
            autoOffMinutes: device.autoOffMinutes || ''
        });
    };

    const saveEdit = async (id) => {
        try {
            const res = await API.put(`/device/${id}`, {
                name: editValues.name,
                powerLimit: Number(editValues.powerLimit),
                autoOffMinutes: editValues.autoOffMinutes ? Number(editValues.autoOffMinutes) : null
            });
            setDevices(devices.map(d => d._id === id ? res.data : d));
            setEditing(null);
        } catch (error) {
            alert(error.response?.data?.message || 'Could not update device');
        }
    };

    const toggleDevice = async (device) => {
        setBusyId(device._id);
        try {
            const action = device.status === 'ON' ? 'turn-off' : 'turn-on';
            const res = await API.post(`/device/${device._id}/${action}`);
            setDevices(devices.map(d => d._id === device._id ? res.data.device : d));
        } catch (error) {
            alert(error.response?.data?.message || 'Could not update device status');
        } finally {
            setBusyId(null);
        }
    };

    const deleteDevice = async (device) => {
        if (!window.confirm(`Delete "${device.name}"? This also removes its usage history.`)) return;
        try {
            await API.delete(`/device/${device._id}`);
            setDevices(devices.filter(d => d._id !== device._id));
        } catch (error) {
            alert(error.response?.data?.message || 'Could not delete device');
        }
    };

    const regenerateKey = async (device) => {
        if (!window.confirm('Regenerate API key? The old key will stop working immediately - update your sensor firmware with the new one.')) return;
        try {
            const res = await API.post(`/device/${device._id}/regenerate-key`);
            setDevices(devices.map(d => d._id === device._id ? { ...d, apiKey: res.data.apiKey } : d));
            setRevealedKeys({ ...revealedKeys, [device._id]: true });
        } catch (error) {
            alert(error.response?.data?.message || 'Could not regenerate key');
        }
    };

    const copyToClipboard = (text) => {
        navigator.clipboard.writeText(text);
    };

    return (
        <div className="flex min-h-screen bg-dark text-white">

            {/* SIDEBAR */}
            <div className="w-64 bg-black border-r border-border p-6">
                <h1 className="text-2xl font-bold text-primary">EnergyAI</h1>
                <div className="mt-10 space-y-4">
                    <Link to="/dashboard" className="block text-gray-400 hover:text-white">Dashboard</Link>
                    <div className="bg-primary/20 p-3 rounded-xl">Devices</div>
                </div>
            </div>

            {/* MAIN */}
            <div className="flex-1 p-8">

                <div className="flex justify-between items-center mb-8">
                    <div>
                        <h1 className="text-4xl font-bold">Devices</h1>
                        <p className="text-gray-400 mt-2">
                            Add sensors, set power limits, and turn devices on/off.
                        </p>
                    </div>
                    <button
                        onClick={() => setShowAddForm(!showAddForm)}
                        className="bg-primary px-6 py-3 rounded-xl font-semibold hover:opacity-90 transition"
                    >
                        + Add Device
                    </button>
                </div>

                {/* ADD DEVICE FORM */}
                {showAddForm && (
                    <div className="bg-card border border-border rounded-2xl p-6 mb-8">
                        <h2 className="text-xl font-bold mb-4">New Device</h2>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div>
                                <label className="text-gray-400 text-sm">Device Name</label>
                                <input
                                    type="text"
                                    placeholder="e.g. Living Room AC"
                                    value={newName}
                                    onChange={(e) => setNewName(e.target.value)}
                                    className="w-full bg-dark border border-border rounded-xl px-4 py-3 mt-1 outline-none focus:border-primary"
                                />
                            </div>
                            <div>
                                <label className="text-gray-400 text-sm">Power Limit (Watts)</label>
                                <input
                                    type="number"
                                    value={newLimit}
                                    onChange={(e) => setNewLimit(e.target.value)}
                                    className="w-full bg-dark border border-border rounded-xl px-4 py-3 mt-1 outline-none focus:border-primary"
                                />
                            </div>
                            <div>
                                <label className="text-gray-400 text-sm">Auto-off delay (minutes, optional)</label>
                                <input
                                    type="number"
                                    placeholder="Default: 5"
                                    value={newAutoOff}
                                    onChange={(e) => setNewAutoOff(e.target.value)}
                                    className="w-full bg-dark border border-border rounded-xl px-4 py-3 mt-1 outline-none focus:border-primary"
                                />
                            </div>
                        </div>
                        <button
                            onClick={handleAddDevice}
                            className="mt-5 bg-primary px-6 py-3 rounded-xl font-semibold hover:opacity-90 transition"
                        >
                            Create Device
                        </button>
                    </div>
                )}

                {/* JUST CREATED - hardware setup panel */}
                {justCreated && (
                    <div className="bg-green-500/10 border border-green-500/30 rounded-2xl p-6 mb-8">
                        <div className="flex justify-between items-start">
                            <h2 className="text-xl font-bold text-green-300 mb-2">
                                "{justCreated.name}" created - connect your sensor
                            </h2>
                            <button onClick={() => setJustCreated(null)} className="text-gray-400 hover:text-white">✕</button>
                        </div>
                        <p className="text-gray-300 text-sm mb-3">
                            Send readings from your ESP32/Arduino to this endpoint, with this device's API key in the header:
                        </p>
                        <div className="bg-black/40 rounded-xl p-4 font-mono text-sm space-y-2 overflow-x-auto">
                            <div>POST {apiBase}/ingest</div>
                            <div>Header: x-api-key: {justCreated.apiKey}</div>
                            <div>Body (JSON): {'{ "power": 742 }'}</div>
                        </div>
                        <button
                            onClick={() => copyToClipboard(justCreated.apiKey)}
                            className="mt-3 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-sm"
                        >
                            Copy API Key
                        </button>
                    </div>
                )}

                {/* DEVICE LIST */}
                {loading ? (
                    <p className="text-gray-400">Loading devices...</p>
                ) : devices.length === 0 ? (
                    <div className="bg-card border border-border rounded-2xl p-10 text-center text-gray-400">
                        No devices yet. Click "+ Add Device" to register your first sensor.
                    </div>
                ) : (
                    <div className="space-y-4">
                        {devices.map((device) => (
                            <div
                                key={device._id}
                                className="bg-card border border-border rounded-2xl p-6"
                            >
                                {editing === device._id ? (
                                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                                        <div>
                                            <label className="text-gray-400 text-xs">Name</label>
                                            <input
                                                value={editValues.name}
                                                onChange={(e) => setEditValues({ ...editValues, name: e.target.value })}
                                                className="w-full bg-dark border border-border rounded-xl px-3 py-2 mt-1"
                                            />
                                        </div>
                                        <div>
                                            <label className="text-gray-400 text-xs">Power Limit (W)</label>
                                            <input
                                                type="number"
                                                value={editValues.powerLimit}
                                                onChange={(e) => setEditValues({ ...editValues, powerLimit: e.target.value })}
                                                className="w-full bg-dark border border-border rounded-xl px-3 py-2 mt-1"
                                            />
                                        </div>
                                        <div>
                                            <label className="text-gray-400 text-xs">Auto-off (min)</label>
                                            <input
                                                type="number"
                                                value={editValues.autoOffMinutes}
                                                onChange={(e) => setEditValues({ ...editValues, autoOffMinutes: e.target.value })}
                                                className="w-full bg-dark border border-border rounded-xl px-3 py-2 mt-1"
                                            />
                                        </div>
                                        <div className="flex gap-2">
                                            <button
                                                onClick={() => saveEdit(device._id)}
                                                className="bg-primary px-4 py-2 rounded-xl text-sm font-semibold"
                                            >
                                                Save
                                            </button>
                                            <button
                                                onClick={() => setEditing(null)}
                                                className="bg-white/10 px-4 py-2 rounded-xl text-sm"
                                            >
                                                Cancel
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex flex-wrap justify-between items-center gap-4">
                                        <div>
                                            <div className="flex items-center gap-3">
                                                <h3 className="text-xl font-bold">{device.name}</h3>
                                                <span className={`
                                                    px-3 py-1 rounded-full text-xs font-semibold
                                                    ${device.status === 'ON'
                                                        ? 'bg-green-500/20 text-green-400'
                                                        : 'bg-gray-500/20 text-gray-400'}
                                                `}>
                                                    ● {device.status}
                                                </span>
                                            </div>
                                            <p className="text-gray-400 text-sm mt-2">
                                                Limit: {device.powerLimit}W &nbsp;•&nbsp;
                                                Auto-off: {device.autoOffMinutes || 'default'} min &nbsp;•&nbsp;
                                                Last seen: {device.lastSeen ? new Date(device.lastSeen).toLocaleString() : 'never'}
                                            </p>

                                            <div className="mt-3 flex items-center gap-2">
                                                {revealedKeys[device._id] ? (
                                                    <code className="bg-black/40 px-3 py-1 rounded-lg text-xs">
                                                        {device.apiKey}
                                                    </code>
                                                ) : (
                                                    <button
                                                        onClick={() => setRevealedKeys({ ...revealedKeys, [device._id]: true })}
                                                        className="text-primary text-xs hover:underline"
                                                    >
                                                        Show API key
                                                    </button>
                                                )}
                                                {revealedKeys[device._id] && (
                                                    <>
                                                        <button
                                                            onClick={() => copyToClipboard(device.apiKey)}
                                                            className="text-gray-400 text-xs hover:text-white"
                                                        >
                                                            Copy
                                                        </button>
                                                        <button
                                                            onClick={() => regenerateKey(device)}
                                                            className="text-red-400 text-xs hover:underline"
                                                        >
                                                            Regenerate
                                                        </button>
                                                    </>
                                                )}
                                            </div>
                                        </div>

                                        <div className="flex gap-2">
                                            <button
                                                disabled={busyId === device._id}
                                                onClick={() => toggleDevice(device)}
                                                className={`
                                                    px-4 py-2 rounded-xl text-sm font-semibold transition
                                                    ${device.status === 'ON'
                                                        ? 'bg-red-500/20 text-red-300 hover:bg-red-500/30'
                                                        : 'bg-green-500/20 text-green-300 hover:bg-green-500/30'}
                                                `}
                                            >
                                                {device.status === 'ON' ? 'Turn OFF' : 'Turn ON'}
                                            </button>
                                            <button
                                                onClick={() => startEdit(device)}
                                                className="bg-white/10 px-4 py-2 rounded-xl text-sm hover:bg-white/20"
                                            >
                                                Edit
                                            </button>
                                            <button
                                                onClick={() => deleteDevice(device)}
                                                className="bg-white/10 px-4 py-2 rounded-xl text-sm hover:bg-red-500/20 hover:text-red-300"
                                            >
                                                Delete
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                )}

            </div>
        </div>
    );
}

export default Devices;
